const { createCrossmint, CrossmintWallets } = require("@crossmint/wallets-sdk");
const fs = require("fs");

async function main() {
  const result = {
    chain: "base-sepolia",
    type: "evm"
  };

  try {
    const apiKey = process.env.CROSSMINT_API_KEY || "your-api-key";
    const recoverySecret = process.env.CROSSMINT_RECOVERY_SECRET || "your-recovery-secret";

    const crossmint = createCrossmint({ apiKey });
    const wallets = CrossmintWallets.from(crossmint);

    const wallet = await wallets.createWallet({
      chain: "base-sepolia",
      recovery: { type: "server", secret: recoverySecret },
    });

    result.address = wallet.address;
  } catch (error) {
    result.error = error.message || String(error);
  }

  fs.writeFileSync("/home/user/wallet_debug_result.json", JSON.stringify(result, null, 2));
}

main().catch((error) => {
  console.error("Fatal error:", error);
  process.exit(1);
});

